-- P08 Boxes, benefits and credits: versioned offers, immutable lots and least-privilege wallet commands.

-- The legacy generic command is no longer a client API. Platform finance may retain it for migration tooling.
revoke all on function public.append_credit_entry(uuid,uuid,text,bigint,text,text,text,text,uuid) from public,anon,authenticated,service_role;

create table public.benefit_definitions(
 id uuid primary key default extensions.gen_random_uuid(), code text not null unique check(code~'^[A-Z][A-Z0-9_]{2,79}$'),
 status text not null default'DRAFT'check(status in('DRAFT','ACTIVE','PAUSED','RETIRED')),created_by uuid not null references auth.users(id),created_at timestamptz not null default clock_timestamp()
);
create table public.benefit_versions(
 id uuid primary key default extensions.gen_random_uuid(),benefit_id uuid not null references public.benefit_definitions(id)on delete restrict,version integer not null check(version>0),
 status text not null check(status in('DRAFT','UNDER_REVIEW','ACTIVE','PAUSED','RETIRED')),benefit_type text not null check(benefit_type in('PLATFORM_FEATURE','SERVICE_UNIT','CREDIT_SERVICE','PRIORITY','QUOTA','ACCESS_RIGHT','SERVICE_SUBSIDY','CONSULTATION','REPORT','CUSTOM')),
 fulfillment_mode text not null check(fulfillment_mode in('AUTOMATED_PLATFORM','MATRICIA_INTERNAL','DIRECT_PROVIDER','SUBCONTRACTOR_POOL','VOLUME_POOL','RFQ')),
 name_fr text not null check(length(btrim(name_fr))between 2 and 200),name_ar text not null check(length(btrim(name_ar))between 2 and 200),
 description_fr text not null check(length(btrim(description_fr))between 3 and 2000),description_ar text not null check(length(btrim(description_ar))between 3 and 2000),
 credit_cost bigint not null check(credit_cost>=0),reference_value_minor bigint not null check(reference_value_minor>=0),internal_cost_minor bigint not null check(internal_cost_minor>=0),currency char(3)not null check(currency~'^[A-Z]{3}$'),
 library_id uuid references public.catalog_libraries(id)on delete restrict,service_id uuid references public.catalog_services(id)on delete restrict,
 quota bigint check(quota is null or quota>0),capacity_rule jsonb not null default'{}'check(jsonb_typeof(capacity_rule)='object'),eligibility_rule jsonb not null default'{}'check(jsonb_typeof(eligibility_rule)='object'),
 cancellation_rule_version text not null check(length(btrim(cancellation_rule_version))between 1 and 80),effective_from timestamptz not null,effective_to timestamptz,
 content_hash text not null check(content_hash~'^[0-9a-f]{64}$'),created_by uuid not null references auth.users(id),created_at timestamptz not null default clock_timestamp(),
 unique(benefit_id,version),unique(benefit_id,id),check(effective_to is null or effective_to>effective_from),check(service_id is null or library_id is not null)
);
create unique index benefit_one_active_version_idx on public.benefit_versions(benefit_id)where status='ACTIVE';

create table public.box_definitions(
 id uuid primary key default extensions.gen_random_uuid(),code text not null unique check(code~'^[A-Z][A-Z0-9_]{2,79}$'),status text not null default'DRAFT'check(status in('DRAFT','ACTIVE','PAUSED','RETIRED')),created_by uuid not null references auth.users(id),created_at timestamptz not null default clock_timestamp()
);
create table public.box_versions(
 id uuid primary key default extensions.gen_random_uuid(),box_id uuid not null references public.box_definitions(id)on delete restrict,version integer not null check(version>0),status text not null check(status in('DRAFT','UNDER_REVIEW','ACTIVE','PAUSED','RETIRED')),
 box_type text not null check(box_type in('FIXED','SEMI_CUSTOM','CUSTOM','ENTERPRISE','MULTI_USER','MULTI_LIBRARY')),name_fr text not null,name_ar text not null,
 credit_budget bigint not null check(credit_budget>=0),rollover_months integer not null check(rollover_months>=0),rules_snapshot jsonb not null check(jsonb_typeof(rules_snapshot)='object'),
 cost_low_minor bigint not null check(cost_low_minor>=0),cost_expected_minor bigint not null check(cost_expected_minor>=0),cost_full_minor bigint not null check(cost_full_minor>=0),currency char(3)not null check(currency~'^[A-Z]{3}$'),
 approval_reference text,content_hash text not null check(content_hash~'^[0-9a-f]{64}$'),effective_from timestamptz not null,effective_to timestamptz,created_by uuid not null references auth.users(id),created_at timestamptz not null default clock_timestamp(),
 unique(box_id,version),unique(box_id,id),check(effective_to is null or effective_to>effective_from),check(status<>'ACTIVE'or cost_full_minor<=cost_expected_minor or approval_reference is not null)
);
create unique index box_one_active_version_idx on public.box_versions(box_id)where status='ACTIVE';
create table public.box_slots(
 id uuid primary key default extensions.gen_random_uuid(),box_version_id uuid not null references public.box_versions(id)on delete restrict,slot_code text not null,slot_kind text not null check(slot_kind in('MANDATORY','OPTIONAL')),minimum_selections integer not null default 0 check(minimum_selections>=0),maximum_selections integer not null check(maximum_selections>=minimum_selections),allowed_benefit_version_ids uuid[]not null default'{}',created_at timestamptz not null default clock_timestamp(),unique(box_version_id,slot_code)
);
create table public.plan_box_rules(
 id uuid primary key default extensions.gen_random_uuid(),plan_version_id uuid not null references public.subscription_plan_versions(id)on delete restrict,box_version_id uuid not null references public.box_versions(id)on delete restrict,status text not null check(status in('ACTIVE','RETIRED')),effective_from timestamptz not null,effective_to timestamptz,rule_snapshot jsonb not null check(jsonb_typeof(rule_snapshot)='object'),created_at timestamptz not null default clock_timestamp(),unique(plan_version_id,box_version_id,effective_from),check(effective_to is null or effective_to>effective_from)
);
create table public.customer_boxes(
 id uuid primary key default extensions.gen_random_uuid(),organization_id uuid not null references public.organizations(id)on delete restrict,subscription_id uuid not null references public.subscriptions(id)on delete restrict,box_version_id uuid not null references public.box_versions(id)on delete restrict,period_start timestamptz not null,period_end timestamptz not null,selections_snapshot jsonb not null check(jsonb_typeof(selections_snapshot)='array'),content_hash text not null check(content_hash~'^[0-9a-f]{64}$'),created_by uuid not null references auth.users(id),created_at timestamptz not null default clock_timestamp(),unique(subscription_id,period_start),check(period_end>period_start)
);

create table public.credit_lots(
 id uuid primary key default extensions.gen_random_uuid(),organization_id uuid not null,wallet_id uuid not null,grant_entry_id bigint not null unique references public.credit_ledger_entries(id)on delete restrict,
 source_type text not null check(source_type in('SUBSCRIPTION_GRANT','EXTRA_PURCHASE','BONUS','PROMOTION','ADMIN_GRANT')),source_reference text not null,quantity bigint not null check(quantity>0),
 expires_at timestamptz not null,library_id uuid references public.catalog_libraries(id)on delete restrict,revenue_value_minor bigint not null default 0 check(revenue_value_minor>=0),currency char(3)not null default'MAD'check(currency~'^[A-Z]{3}$'),
 rule_version text not null,created_by uuid not null references auth.users(id),created_at timestamptz not null default clock_timestamp(),foreign key(organization_id,wallet_id)references public.credit_wallets(organization_id,id)on delete restrict,check(expires_at>created_at)
);
create table public.benefit_redemptions(
 id uuid primary key default extensions.gen_random_uuid(),organization_id uuid not null,wallet_id uuid not null,benefit_version_id uuid not null references public.benefit_versions(id)on delete restrict,
 units bigint not null check(units>0),credit_cost_snapshot bigint not null check(credit_cost_snapshot>=0),reserved_credits bigint not null check(reserved_credits>0),status text not null check(status in('RESERVED','SCHEDULED','IN_PROGRESS','DELIVERED','CONSUMED','CANCELLED','REFUNDED','EXPIRED')),
 reservation_expires_at timestamptz not null,delivery_proof_hash text,correlation_id uuid not null,created_by uuid not null references auth.users(id),created_at timestamptz not null default clock_timestamp(),updated_at timestamptz not null default clock_timestamp(),row_version bigint not null default 1 check(row_version>0),
 foreign key(organization_id,wallet_id)references public.credit_wallets(organization_id,id)on delete restrict,check(delivery_proof_hash is null or delivery_proof_hash~'^[0-9a-f]{64}$')
);
create table public.credit_lot_movements(
 id bigint generated always as identity primary key,organization_id uuid not null,credit_lot_id uuid not null references public.credit_lots(id)on delete restrict,redemption_id uuid not null references public.benefit_redemptions(id)on delete restrict,
 movement_type text not null check(movement_type in('RESERVE','RELEASE','CONSUME')),quantity bigint not null check(quantity>0),idempotency_scope text not null,idempotency_key text not null,correlation_id uuid not null,created_by uuid not null references auth.users(id),occurred_at timestamptz not null default clock_timestamp(),
 unique(organization_id,idempotency_scope,idempotency_key,credit_lot_id),unique(credit_lot_id,redemption_id,movement_type)
);
create table public.benefit_redemption_events(
 id bigint generated always as identity primary key,organization_id uuid not null,redemption_id uuid not null references public.benefit_redemptions(id)on delete restrict,from_status text,to_status text not null,reason_code text not null,proof_hash text,idempotency_key text not null,correlation_id uuid not null,actor_user_id uuid not null references auth.users(id),occurred_at timestamptz not null default clock_timestamp(),unique(redemption_id,idempotency_key),check(proof_hash is null or proof_hash~'^[0-9a-f]{64}$')
);

create function private.credits_admin_access(p_actor uuid default auth.uid())returns boolean language sql stable security definer set search_path=pg_catalog,private as $$select private.has_platform_role(array['SUPER_ADMIN','MATRICIA_ADMIN','FINANCE_MANAGER'],p_actor)$$;
create function private.credits_client_access(p_org uuid,p_actor uuid default auth.uid())returns boolean language sql stable security definer set search_path=pg_catalog,private as $$select private.has_org_role(p_org,array['CLIENT_OWNER','CLIENT_ADMIN','CLIENT_ACCOUNTING'],p_actor)or private.credits_admin_access(p_actor)$$;
create function private.begin_credit_command(p_org uuid,p_scope text,p_key text,p_hash text,p_actor uuid)returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$declare v public.idempotency_keys%rowtype;n integer;begin if length(p_key)not between 8 and 200 or p_hash!~'^[0-9a-f]{64}$'then raise exception'INVALID_IDEMPOTENCY'using errcode='22023';end if;insert into public.idempotency_keys(organization_id,operation_scope,key,request_hash,created_by,expires_at)values(p_org,p_scope,p_key,p_hash,p_actor,now()+interval'30 days')on conflict do nothing;get diagnostics n=row_count;if n=1 then return null;end if;select*into v from public.idempotency_keys where organization_id=p_org and operation_scope=p_scope and key=p_key for update;if v.request_hash<>p_hash then raise exception'IDEMPOTENCY_PAYLOAD_MISMATCH'using errcode='22000';end if;if v.status='COMPLETED'then return v.response_body;end if;raise exception'IDEMPOTENCY_IN_PROGRESS'using errcode='55000';end$$;
create function private.finish_credit_command(p_org uuid,p_scope text,p_key text,p_response jsonb)returns void language sql security definer set search_path=pg_catalog,public as $$update public.idempotency_keys set status='COMPLETED',response_code=201,response_body=p_response,completed_at=clock_timestamp()where organization_id=p_org and operation_scope=p_scope and key=p_key and status='PROCESSING'$$;

create function public.ensure_client_credit_wallet(p_organization_id uuid,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$declare a uuid:=auth.uid();w uuid;h text;r jsonb;begin if a is null or not private.credits_client_access(p_organization_id,a)then raise exception'CREDIT_WALLET_PROVISION_DENIED'using errcode='42501';end if;perform 1 from public.organizations where id=p_organization_id and status='ACTIVE'for update;if not found then raise exception'ORGANIZATION_NOT_ACTIVE'using errcode='23514';end if;h:=private.canonical_request_hash(jsonb_build_object('organization',p_organization_id,'wallet_type','CLIENT'));r:=private.begin_credit_command(p_organization_id,'credits.wallet.ensure',p_idempotency_key,h,a);if r is not null then return r;end if;insert into public.credit_wallets(organization_id,wallet_type)values(p_organization_id,'CLIENT')on conflict(organization_id,wallet_type)do nothing;select id into w from public.credit_wallets where organization_id=p_organization_id and wallet_type='CLIENT';r:=jsonb_build_object('outcome','CREDIT_WALLET_READY','wallet_id',w);insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(p_organization_id,a,'USER','credits.wallet_ready','credit_wallet',w::text,p_correlation_id,'{}',repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(p_organization_id,'credit_wallet',w::text,'CreditWalletReadyV1',p_correlation_id,r,p_idempotency_key);perform private.finish_credit_command(p_organization_id,'credits.wallet.ensure',p_idempotency_key,r);return r;end$$;

create function public.issue_credits(p_organization_id uuid,p_wallet_id uuid,p_source_type text,p_quantity bigint,p_expires_at timestamptz,p_library_id uuid,p_source_reference text,p_revenue_value_minor bigint,p_rule_version text,p_approval_reference text,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$declare a uuid:=auth.uid();h text;r jsonb;e bigint;l uuid;begin if a is null or not private.credits_admin_access(a)then raise exception'CREDIT_ISSUE_DENIED'using errcode='42501';end if;if p_source_type not in('SUBSCRIPTION_GRANT','EXTRA_PURCHASE','BONUS','PROMOTION','ADMIN_GRANT')or p_quantity<=0 or p_expires_at<=clock_timestamp()or p_revenue_value_minor<0 or length(btrim(coalesce(p_source_reference,'')))<3 or length(btrim(coalesce(p_rule_version,'')))<1 or(p_source_type in('BONUS','PROMOTION','ADMIN_GRANT')and length(btrim(coalesce(p_approval_reference,'')))<3)then raise exception'INVALID_CREDIT_ISSUE'using errcode='22023';end if;perform 1 from public.credit_wallets where organization_id=p_organization_id and id=p_wallet_id and wallet_type='CLIENT'for update;if not found then raise exception'CLIENT_WALLET_NOT_FOUND'using errcode='P0002';end if;h:=private.canonical_request_hash(jsonb_build_object('organization',p_organization_id,'wallet',p_wallet_id,'source_type',p_source_type,'quantity',p_quantity,'expires_at',p_expires_at,'library',p_library_id,'source',p_source_reference,'revenue_minor',p_revenue_value_minor,'rule_version',p_rule_version,'approval',p_approval_reference));r:=private.begin_credit_command(p_organization_id,'credits.issue',p_idempotency_key,h,a);if r is not null then return r;end if;insert into public.credit_ledger_entries(organization_id,wallet_id,entry_type,quantity,idempotency_scope,idempotency_key,correlation_id,reference_type,reference_id,created_by)values(p_organization_id,p_wallet_id,'GRANT',p_quantity,'credits.issue',p_idempotency_key,p_correlation_id,p_source_type,p_source_reference,a)returning id into e;insert into public.credit_lots(organization_id,wallet_id,grant_entry_id,source_type,source_reference,quantity,expires_at,library_id,revenue_value_minor,rule_version,created_by)values(p_organization_id,p_wallet_id,e,p_source_type,p_source_reference,p_quantity,p_expires_at,p_library_id,p_revenue_value_minor,p_rule_version,a)returning id into l;r:=jsonb_build_object('outcome','CREDITS_ISSUED','wallet_id',p_wallet_id,'credit_lot_id',l,'entry_id',e,'quantity',p_quantity);insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(p_organization_id,a,'USER','credits.issued','credit_lot',l::text,p_correlation_id,jsonb_build_object('source_type',p_source_type,'quantity',p_quantity,'approval_reference',p_approval_reference),repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(p_organization_id,'credit_wallet',p_wallet_id::text,'CreditsGrantedV1',p_correlation_id,r,p_idempotency_key);perform private.finish_credit_command(p_organization_id,'credits.issue',p_idempotency_key,r);return r;end$$;

create function public.reserve_benefit_credits(p_organization_id uuid,p_wallet_id uuid,p_benefit_version_id uuid,p_units bigint,p_reservation_expires_at timestamptz,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$declare a uuid:=auth.uid();b public.benefit_versions%rowtype;needed bigint;remaining bigint;take_qty bigint;red uuid;e bigint;h text;r jsonb;x record;begin if a is null or not private.credits_client_access(p_organization_id,a)then raise exception'CREDIT_RESERVE_DENIED'using errcode='42501';end if;if p_units<=0 or p_reservation_expires_at<=clock_timestamp()then raise exception'INVALID_CREDIT_RESERVATION'using errcode='22023';end if;perform 1 from public.credit_wallets where organization_id=p_organization_id and id=p_wallet_id and wallet_type='CLIENT'for update;if not found then raise exception'CLIENT_WALLET_NOT_FOUND'using errcode='P0002';end if;select*into b from public.benefit_versions where id=p_benefit_version_id and status='ACTIVE'and effective_from<=clock_timestamp()and(effective_to is null or effective_to>clock_timestamp());if not found then raise exception'ACTIVE_BENEFIT_VERSION_REQUIRED'using errcode='23514';end if;needed:=b.credit_cost*p_units;if needed<=0 then raise exception'PAID_CREDIT_BENEFIT_REQUIRED'using errcode='23514';end if;h:=private.canonical_request_hash(jsonb_build_object('organization',p_organization_id,'wallet',p_wallet_id,'benefit_version',b.id,'units',p_units,'expires_at',p_reservation_expires_at));r:=private.begin_credit_command(p_organization_id,'credits.benefit.reserve',p_idempotency_key,h,a);if r is not null then return r;end if;insert into public.benefit_redemptions(organization_id,wallet_id,benefit_version_id,units,credit_cost_snapshot,reserved_credits,status,reservation_expires_at,correlation_id,created_by)values(p_organization_id,p_wallet_id,b.id,p_units,b.credit_cost,needed,'RESERVED',p_reservation_expires_at,p_correlation_id,a)returning id into red;remaining:=needed;for x in select l.id,l.quantity-coalesce((select sum(case when m.movement_type='RESERVE'then m.quantity when m.movement_type='RELEASE'then-m.quantity else 0 end)from public.credit_lot_movements m where m.credit_lot_id=l.id),0)available from public.credit_lots l where l.organization_id=p_organization_id and l.wallet_id=p_wallet_id and l.expires_at>p_reservation_expires_at and(l.library_id is null or l.library_id=b.library_id)order by l.expires_at,l.created_at,l.id for update of l loop exit when remaining=0;if x.available>0 then take_qty:=least(x.available,remaining);insert into public.credit_lot_movements(organization_id,credit_lot_id,redemption_id,movement_type,quantity,idempotency_scope,idempotency_key,correlation_id,created_by)values(p_organization_id,x.id,red,'RESERVE',take_qty,'credits.benefit.reserve',p_idempotency_key,p_correlation_id,a);remaining:=remaining-take_qty;end if;end loop;if remaining<>0 then raise exception'INSUFFICIENT_ELIGIBLE_CREDITS'using errcode='23514';end if;insert into public.credit_ledger_entries(organization_id,wallet_id,entry_type,quantity,idempotency_scope,idempotency_key,correlation_id,reference_type,reference_id,created_by)values(p_organization_id,p_wallet_id,'RESERVE',-needed,'credits.benefit.reserve',p_idempotency_key,p_correlation_id,'BENEFIT_REDEMPTION',red::text,a)returning id into e;insert into public.benefit_redemption_events(organization_id,redemption_id,from_status,to_status,reason_code,idempotency_key,correlation_id,actor_user_id)values(p_organization_id,red,null,'RESERVED','CLIENT_REQUEST',p_idempotency_key,p_correlation_id,a);r:=jsonb_build_object('outcome','BENEFIT_RESERVED','redemption_id',red,'entry_id',e,'reserved_credits',needed,'benefit_version_id',b.id);insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(p_organization_id,a,'USER','benefit.reserved','benefit_redemption',red::text,p_correlation_id,r,repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(p_organization_id,'benefit_redemption',red::text,'BenefitReservedV1',p_correlation_id,r,p_idempotency_key);perform private.finish_credit_command(p_organization_id,'credits.benefit.reserve',p_idempotency_key,r);return r;end$$;

create function public.release_benefit_credits(p_redemption_id uuid,p_reason_code text,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$declare a uuid:=auth.uid();d public.benefit_redemptions%rowtype;h text;r jsonb;e bigint;x record;begin select*into d from public.benefit_redemptions where id=p_redemption_id for update;if a is null or not found or not private.credits_client_access(d.organization_id,a)then raise exception'CREDIT_RELEASE_DENIED'using errcode='42501';end if;h:=private.canonical_request_hash(jsonb_build_object('redemption',d.id,'reason',p_reason_code));r:=private.begin_credit_command(d.organization_id,'credits.benefit.release',p_idempotency_key,h,a);if r is not null then return r;end if;if d.status<>'RESERVED'or length(btrim(coalesce(p_reason_code,'')))not between 3 and 80 then raise exception'REDEMPTION_NOT_RELEASABLE'using errcode='55000';end if;for x in select credit_lot_id,quantity from public.credit_lot_movements where redemption_id=d.id and movement_type='RESERVE'loop insert into public.credit_lot_movements(organization_id,credit_lot_id,redemption_id,movement_type,quantity,idempotency_scope,idempotency_key,correlation_id,created_by)values(d.organization_id,x.credit_lot_id,d.id,'RELEASE',x.quantity,'credits.benefit.release',p_idempotency_key,p_correlation_id,a);end loop;insert into public.credit_ledger_entries(organization_id,wallet_id,entry_type,quantity,idempotency_scope,idempotency_key,correlation_id,reference_type,reference_id,created_by)values(d.organization_id,d.wallet_id,'RELEASE',d.reserved_credits,'credits.benefit.release',p_idempotency_key,p_correlation_id,'BENEFIT_REDEMPTION',d.id::text,a)returning id into e;update public.benefit_redemptions set status='CANCELLED',updated_at=clock_timestamp(),row_version=row_version+1 where id=d.id;insert into public.benefit_redemption_events(organization_id,redemption_id,from_status,to_status,reason_code,idempotency_key,correlation_id,actor_user_id)values(d.organization_id,d.id,d.status,'CANCELLED',p_reason_code,p_idempotency_key,p_correlation_id,a);r:=jsonb_build_object('outcome','BENEFIT_RELEASED','redemption_id',d.id,'entry_id',e,'released_credits',d.reserved_credits);insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(d.organization_id,a,'USER','benefit.released','benefit_redemption',d.id::text,p_correlation_id,r,repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(d.organization_id,'benefit_redemption',d.id::text,'BenefitReleasedV1',p_correlation_id,r,p_idempotency_key);perform private.finish_credit_command(d.organization_id,'credits.benefit.release',p_idempotency_key,r);return r;end$$;

create function public.consume_benefit_credits(p_redemption_id uuid,p_delivery_proof_hash text,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$declare a uuid:=auth.uid();d public.benefit_redemptions%rowtype;h text;r jsonb;release_entry bigint;consume_entry bigint;x record;begin select*into d from public.benefit_redemptions where id=p_redemption_id for update;if a is null or not found or not private.credits_client_access(d.organization_id,a)then raise exception'CREDIT_CONSUME_DENIED'using errcode='42501';end if;h:=private.canonical_request_hash(jsonb_build_object('redemption',d.id,'proof_hash',p_delivery_proof_hash));r:=private.begin_credit_command(d.organization_id,'credits.benefit.consume',p_idempotency_key,h,a);if r is not null then return r;end if;if d.status not in('RESERVED','DELIVERED')or p_delivery_proof_hash!~'^[0-9a-f]{64}$'then raise exception'REDEMPTION_NOT_CONSUMABLE'using errcode='55000';end if;for x in select credit_lot_id,quantity from public.credit_lot_movements where redemption_id=d.id and movement_type='RESERVE'loop insert into public.credit_lot_movements(organization_id,credit_lot_id,redemption_id,movement_type,quantity,idempotency_scope,idempotency_key,correlation_id,created_by)values(d.organization_id,x.credit_lot_id,d.id,'CONSUME',x.quantity,'credits.benefit.consume',p_idempotency_key,p_correlation_id,a);end loop;insert into public.credit_ledger_entries(organization_id,wallet_id,entry_type,quantity,idempotency_scope,idempotency_key,correlation_id,reference_type,reference_id,created_by)values(d.organization_id,d.wallet_id,'RELEASE',d.reserved_credits,'credits.benefit.consume.release',p_idempotency_key,p_correlation_id,'BENEFIT_REDEMPTION',d.id::text,a)returning id into release_entry;insert into public.credit_ledger_entries(organization_id,wallet_id,entry_type,quantity,idempotency_scope,idempotency_key,correlation_id,reference_type,reference_id,created_by)values(d.organization_id,d.wallet_id,'CONSUME',-d.reserved_credits,'credits.benefit.consume',p_idempotency_key,p_correlation_id,'BENEFIT_REDEMPTION',d.id::text,a)returning id into consume_entry;update public.benefit_redemptions set status='CONSUMED',delivery_proof_hash=p_delivery_proof_hash,updated_at=clock_timestamp(),row_version=row_version+1 where id=d.id;insert into public.benefit_redemption_events(organization_id,redemption_id,from_status,to_status,reason_code,proof_hash,idempotency_key,correlation_id,actor_user_id)values(d.organization_id,d.id,d.status,'CONSUMED','DELIVERY_PROVED',p_delivery_proof_hash,p_idempotency_key,p_correlation_id,a);r:=jsonb_build_object('outcome','BENEFIT_CONSUMED','redemption_id',d.id,'consume_entry_id',consume_entry,'consumed_credits',d.reserved_credits);insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(d.organization_id,a,'USER','benefit.consumed','benefit_redemption',d.id::text,p_correlation_id,r,repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(d.organization_id,'benefit_redemption',d.id::text,'BenefitConsumedV1',p_correlation_id,r,p_idempotency_key);perform private.finish_credit_command(d.organization_id,'credits.benefit.consume',p_idempotency_key,r);return r;end$$;

create function public.expire_credit_lot(p_credit_lot_id uuid,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$declare a uuid:=auth.uid();l public.credit_lots%rowtype;available bigint;h text;r jsonb;e bigint;begin if a is null or not private.credits_admin_access(a)then raise exception'CREDIT_EXPIRY_DENIED'using errcode='42501';end if;select*into l from public.credit_lots where id=p_credit_lot_id for update;if not found then raise exception'CREDIT_LOT_NOT_FOUND'using errcode='P0002';end if;h:=private.canonical_request_hash(jsonb_build_object('credit_lot',l.id,'expires_at',l.expires_at));r:=private.begin_credit_command(l.organization_id,'credits.lot.expire',p_idempotency_key,h,a);if r is not null then return r;end if;if l.expires_at>clock_timestamp()then raise exception'CREDIT_LOT_NOT_EXPIRED'using errcode='55000';end if;select l.quantity-coalesce(sum(case when m.movement_type='RESERVE'then m.quantity when m.movement_type='RELEASE'then-m.quantity else 0 end),0)into available from public.credit_lot_movements m where m.credit_lot_id=l.id;if exists(select 1 from public.credit_ledger_entries x where x.organization_id=l.organization_id and x.wallet_id=l.wallet_id and x.entry_type='EXPIRE'and x.reference_type='CREDIT_LOT'and x.reference_id=l.id::text)then raise exception'CREDIT_LOT_ALREADY_EXPIRED'using errcode='55000';end if;if available<0 then raise exception'CREDIT_LOT_STATE_INVALID'using errcode='23514';end if;if available>0 then insert into public.credit_ledger_entries(organization_id,wallet_id,entry_type,quantity,idempotency_scope,idempotency_key,correlation_id,reference_type,reference_id,created_by)values(l.organization_id,l.wallet_id,'EXPIRE',-available,'credits.lot.expire',p_idempotency_key,p_correlation_id,'CREDIT_LOT',l.id::text,a)returning id into e;end if;r:=jsonb_build_object('outcome','CREDIT_LOT_EXPIRED','credit_lot_id',l.id,'entry_id',e,'expired_credits',available);insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(l.organization_id,a,'USER','credits.lot_expired','credit_lot',l.id::text,p_correlation_id,r,repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(l.organization_id,'credit_wallet',l.wallet_id::text,'CreditLotExpiredV1',p_correlation_id,r,p_idempotency_key);perform private.finish_credit_command(l.organization_id,'credits.lot.expire',p_idempotency_key,r);return r;end$$;

do $$declare t text;begin foreach t in array array['benefit_definitions','benefit_versions','box_definitions','box_versions','box_slots','plan_box_rules','customer_boxes','credit_lots','benefit_redemptions','credit_lot_movements','benefit_redemption_events']loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);end loop;end$$;
create policy benefit_definitions_read on public.benefit_definitions for select to authenticated using(status='ACTIVE'or private.credits_admin_access());
create policy benefit_versions_read on public.benefit_versions for select to authenticated using(status='ACTIVE'or private.credits_admin_access());
create policy box_definitions_read on public.box_definitions for select to authenticated using(status='ACTIVE'or private.credits_admin_access());
create policy box_versions_read on public.box_versions for select to authenticated using(status='ACTIVE'or private.credits_admin_access());
create policy box_slots_read on public.box_slots for select to authenticated using(exists(select 1 from public.box_versions v where v.id=box_version_id and(v.status='ACTIVE'or private.credits_admin_access())));
create policy plan_box_rules_read on public.plan_box_rules for select to authenticated using(status='ACTIVE'or private.credits_admin_access());
create policy customer_boxes_tenant_read on public.customer_boxes for select to authenticated using(private.credits_client_access(organization_id));
create policy credit_lots_tenant_read on public.credit_lots for select to authenticated using(private.credits_client_access(organization_id));
create policy benefit_redemptions_tenant_read on public.benefit_redemptions for select to authenticated using(private.credits_client_access(organization_id));
create policy credit_lot_movements_tenant_read on public.credit_lot_movements for select to authenticated using(private.credits_client_access(organization_id));
create policy benefit_redemption_events_tenant_read on public.benefit_redemption_events for select to authenticated using(private.credits_client_access(organization_id));
grant select on public.benefit_definitions,public.benefit_versions,public.box_definitions,public.box_versions,public.box_slots,public.plan_box_rules,public.customer_boxes,public.credit_lots,public.benefit_redemptions,public.credit_lot_movements,public.benefit_redemption_events to authenticated;

create trigger benefit_versions_immutable before update or delete on public.benefit_versions for each row execute function private.prevent_update_delete();create trigger box_versions_immutable before update or delete on public.box_versions for each row execute function private.prevent_update_delete();create trigger box_slots_immutable before update or delete on public.box_slots for each row execute function private.prevent_update_delete();create trigger plan_box_rules_immutable before update or delete on public.plan_box_rules for each row execute function private.prevent_update_delete();create trigger customer_boxes_immutable before update or delete on public.customer_boxes for each row execute function private.prevent_update_delete();create trigger credit_lots_immutable before update or delete on public.credit_lots for each row execute function private.prevent_update_delete();create trigger credit_lot_movements_immutable before update or delete on public.credit_lot_movements for each row execute function private.prevent_update_delete();create trigger benefit_redemption_events_immutable before update or delete on public.benefit_redemption_events for each row execute function private.prevent_update_delete();

revoke all on function private.credits_admin_access(uuid),private.credits_client_access(uuid,uuid),private.begin_credit_command(uuid,text,text,text,uuid),private.finish_credit_command(uuid,text,text,jsonb)from public,anon,authenticated,service_role;grant execute on function private.credits_admin_access(uuid),private.credits_client_access(uuid,uuid)to authenticated;
revoke all on function public.ensure_client_credit_wallet(uuid,text,uuid),public.issue_credits(uuid,uuid,text,bigint,timestamptz,uuid,text,bigint,text,text,text,uuid),public.reserve_benefit_credits(uuid,uuid,uuid,bigint,timestamptz,text,uuid),public.release_benefit_credits(uuid,text,text,uuid),public.consume_benefit_credits(uuid,text,text,uuid)from public,anon,authenticated,service_role;
grant execute on function public.ensure_client_credit_wallet(uuid,text,uuid),public.issue_credits(uuid,uuid,text,bigint,timestamptz,uuid,text,bigint,text,text,text,uuid),public.reserve_benefit_credits(uuid,uuid,uuid,bigint,timestamptz,text,uuid),public.release_benefit_credits(uuid,text,text,uuid),public.consume_benefit_credits(uuid,text,text,uuid)to authenticated;
create index benefit_versions_active_idx on public.benefit_versions(status,effective_from,effective_to);create index box_versions_active_idx on public.box_versions(status,effective_from,effective_to);create index customer_boxes_org_period_idx on public.customer_boxes(organization_id,period_end desc);create index credit_lots_fifo_idx on public.credit_lots(organization_id,wallet_id,expires_at,created_at);create index redemptions_org_status_idx on public.benefit_redemptions(organization_id,status,reservation_expires_at);create index lot_movements_redemption_idx on public.credit_lot_movements(redemption_id,movement_type,id);
revoke all on function public.expire_credit_lot(uuid,text,uuid)from public,anon,authenticated,service_role;grant execute on function public.expire_credit_lot(uuid,text,uuid)to authenticated;
